mapper.select:
SELECT rid.id, rid.subtitle_id, rid.label, rid.display_order, rid.created_at, rid.updated_at
FROM report_item_definitions rid
JOIN report_item_subtitles rist ON rist.id = rid.subtitle_id
JOIN report_item_groups rig ON rig.id = rist.group_id
JOIN goals g ON g.id = rig.goal_id
WHERE rig.student_id = #{studentId}
  AND g.start_date <= #{reportDate}
  AND g.end_date >= #{reportDate}
ORDER BY rist.display_order ASC, rid.display_order ASC

SELECT id, subtitle_id, label, display_order, created_at, updated_at
FROM report_item_definitions
WHERE id = #{id}

mapper.update:
UPDATE report_item_definitions
SET label = #{label}
WHERE id = #{id}

UPDATE report_item_definitions
SET display_order = #{displayOrder}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM report_item_responses
WHERE report_item_definition_id = #{definitionId}

SELECT COALESCE(MAX(display_order), -1)
FROM report_item_definitions
WHERE subtitle_id = #{subtitleId}
